import { Router } from "express";
import { pool } from "@workspace/db";
import { logger } from "../../lib/logger";
import { requireAuth, requireRole, hashPassword } from "../../lib/auth";

const router = Router();

const PIANO_NORM_U: Record<string, string> = { gratuito: "mister", base: "mister_pro", premium: "societa" };
const COLLAB_LIMITS: Record<string, number> = { mister: 0, mister_pro: 6, societa: Infinity, demo: Infinity };
const COLLAB_ROLES = new Set(["allenatore", "mister", "dirigente", "preparatore_portieri", "mister_admin"]);

async function getCollabLimit(societyId: number): Promise<number> {
  const [rows] = await pool.execute("SELECT piano FROM societies WHERE id = ?", [societyId]) as [any[], any];
  const raw = rows[0]?.piano || "demo";
  const norm = PIANO_NORM_U[raw] || raw;
  return COLLAB_LIMITS[norm] ?? 0;
}

// GET /api/v2/users/roles
// Restituisce id+ruolo di tutti gli utenti attivi della società corrente.
// Accessibile a QUALSIASI utente autenticato (i ruoli sono già nel blob
// USERS_DB condiviso, niente nuova esposizione). Usato dal client per
// riallineare blob.role ← MySQL.ruolo (autorevole) e ripristinare account
// "corrotti" da setViewMode pre-fix. Idempotente.
router.get("/users/roles", requireAuth, async (req, res) => {
  const { societyId } = req.jwtUser!;
  try {
    const [rows] = (await pool.execute(
      "SELECT id, ruolo FROM users WHERE society_id = ?",
      [societyId]
    )) as [any[], any];
    return res.json({
      roles: rows.map((r: any) => ({ id: r.id, ruolo: r.ruolo })),
    });
  } catch (e: any) {
    logger.error({ err: e }, "GET users/roles error");
    return res.status(500).json({ error: "server_error" });
  }
});

// GET /api/v2/users/id-email-map
// "Rosetta Stone" per il remap blob_id → MySQL_id usato da _persistAdhocMembers
// (FE chat ad-hoc). Restituisce SOLO id+email degli utenti ATTIVI della stessa
// societa' del JWT. Accessibile a QUALSIASI utente autenticato: l'email e' gia'
// conosciuta dai membri della stessa societa' (presente nel blob locale USERS_DB)
// → nessuna nuova esposizione. Niente nome/cognome/ruolo/leva/telefono/permessi/
// figli/stato (quelli restano admin-only su GET /users).
// Stesso pattern di /users/roles: route consumer scoped con payload minimo.
router.get("/users/id-email-map", requireAuth, async (req, res) => {
  const { societyId } = req.jwtUser!;
  try {
    // Stesso scope di GET /users (society_id del JWT, niente filtro per stato/leva).
    const [rows] = (await pool.execute(
      "SELECT id, email FROM users WHERE society_id = ?",
      [societyId]
    )) as [any[], any];
    return res.json(
      (rows as any[]).map((r: any) => ({ id: r.id, email: r.email }))
    );
  } catch (e: any) {
    logger.error({ err: e }, "GET users/id-email-map error");
    return res.status(500).json({ error: "server_error" });
  }
});

// GET /api/v2/users
router.get("/users", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId } = req.jwtUser!;
  try {
    const [rows] = (await pool.execute(
      `SELECT id, nome, cognome, email, ruolo, leva, stato, temp_password, figli, phone, permissions, is_account_owner, created_at
       FROM users WHERE society_id = ? ORDER BY cognome, nome`,
      [societyId]
    )) as [any[], any];

    return res.json(rows.map(u => ({
      ...u,
      figli: u.figli ? JSON.parse(u.figli) : [],
      tempPassword: u.temp_password === 1,
      isAccountOwner: u.is_account_owner === 1,
      permissions: u.permissions
        ? (typeof u.permissions === "string" ? JSON.parse(u.permissions) : u.permissions)
        : null,
    })));
  } catch (e: any) {
    logger.error({ err: e }, "GET users error");
    return res.status(500).json({ error: "server_error" });
  }
});

// POST /api/v2/users
router.post("/users", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId } = req.jwtUser!;
  const { nome, cognome, email, password, ruolo, leva, figli, phone, permissions } = req.body as Record<string, any>;

  if (!nome || !cognome || !email || !password || !ruolo) {
    return res.status(400).json({ error: "missing_fields" });
  }

  const normalizedEmail = email.trim().toLowerCase();
  const hash = hashPassword(password);

  try {
    if (COLLAB_ROLES.has(ruolo)) {
      const maxCollab = await getCollabLimit(societyId);
      if (isFinite(maxCollab)) {
        const [cnt] = await pool.execute(
          `SELECT COUNT(*) as n FROM users WHERE society_id = ? AND ruolo IN ('allenatore','mister','dirigente','preparatore_portieri','mister_admin') AND stato != 'sospeso'`,
          [societyId]
        ) as [any[], any];
        if (cnt[0].n >= maxCollab) {
          return res.status(403).json({ error: "plan_limit_reached", limitType: "collaboratori", current: cnt[0].n, max: maxCollab });
        }
      }
    }

    const [existing] = (await pool.execute(
      "SELECT id FROM users WHERE LOWER(email) = ? AND society_id = ?",
      [normalizedEmail, societyId]
    )) as [any[], any];
    if (existing.length) return res.status(409).json({ error: "email_exists" });

    const [result] = (await pool.execute(
      `INSERT INTO users (society_id, nome, cognome, email, password_hash, ruolo, leva, figli, phone, permissions, temp_password)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, TRUE)`,
      [societyId, nome.trim(), cognome.trim(), normalizedEmail, hash, ruolo,
       leva ?? null, figli ? JSON.stringify(figli) : null,
       phone ?? null, permissions ? JSON.stringify(permissions) : null]
    )) as [any, any];

    return res.status(201).json({ id: result.insertId });
  } catch (e: any) {
    logger.error({ err: e }, "POST user error");
    return res.status(500).json({ error: "server_error" });
  }
});

// PUT /api/v2/users/:id
router.put("/users/:id", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId } = req.jwtUser!;
  const { nome, cognome, email, password, ruolo, leva, stato, figli, phone, permissions } = req.body as Record<string, any>;

  try {
    // Se il ruolo sta cambiando verso un ruolo collaboratore, verifica il limite
    if (ruolo && COLLAB_ROLES.has(ruolo)) {
      const [curRows] = await pool.execute(
        "SELECT ruolo FROM users WHERE id = ? AND society_id = ?",
        [req.params.id, societyId]
      ) as [any[], any];
      const currentRuolo = curRows[0]?.ruolo;
      if (currentRuolo && !COLLAB_ROLES.has(currentRuolo)) {
        const maxCollab = await getCollabLimit(societyId);
        if (isFinite(maxCollab)) {
          const [cnt] = await pool.execute(
            `SELECT COUNT(*) as n FROM users WHERE society_id = ? AND ruolo IN ('allenatore','mister','dirigente','preparatore_portieri','mister_admin') AND stato != 'sospeso' AND id != ?`,
            [societyId, req.params.id]
          ) as [any[], any];
          if (cnt[0].n >= maxCollab) {
            return res.status(403).json({ error: "plan_limit_reached", limitType: "collaboratori", current: cnt[0].n, max: maxCollab });
          }
        }
      }
    }

    const updates: string[] = [];
    const params: any[] = [];

    if (nome)    { updates.push("nome = ?");    params.push(nome.trim()); }
    if (cognome) { updates.push("cognome = ?"); params.push(cognome.trim()); }
    if (email)   { updates.push("email = ?");   params.push(email.trim().toLowerCase()); }
    if (ruolo)   { updates.push("ruolo = ?");   params.push(ruolo); }
    if (leva !== undefined) { updates.push("leva = ?"); params.push(leva ?? null); }
    if (stato)   { updates.push("stato = ?");   params.push(stato); }
    if (figli !== undefined) { updates.push("figli = ?"); params.push(figli ? JSON.stringify(figli) : null); }
    if (phone !== undefined) { updates.push("phone = ?"); params.push(phone ?? null); }
    if (permissions !== undefined) { updates.push("permissions = ?"); params.push(permissions ? JSON.stringify(permissions) : null); }
    if (password) {
      updates.push("password_hash = ?");
      updates.push("temp_password = TRUE");
      params.push(hashPassword(password));
    }

    if (!updates.length) return res.status(400).json({ error: "nothing_to_update" });

    params.push(req.params.id, societyId);
    const [result] = (await pool.execute(
      `UPDATE users SET ${updates.join(", ")} WHERE id = ? AND society_id = ?`,
      params
    )) as [any, any];

    if (!result.affectedRows) return res.status(404).json({ error: "not_found" });
    return res.json({ ok: true });
  } catch (e: any) {
    logger.error({ err: e }, "PUT user error");
    return res.status(500).json({ error: "server_error" });
  }
});

// PATCH /api/v2/users/:id — sync mirato ruolo/leva/stato a MySQL.
// Usato dal FE (saveUser in Gestione Utenti) per propagare la promozione/declassamento ruolo
// che oggi vive solo nel blob USERS_DB. Gating LIVE (legge users.ruolo del chiamante da MySQL,
// non si fida del JWT che potrebbe essere stale) + whitelist ruoli (no email/password/permissions).
const PATCH_RUOLO_WHITELIST = new Set([
  "admin", "allenatore", "mister", "dirigente", "preparatore_portieri", "mister_admin",
  "genitore", "nonno", "giocatore", "pendente",
]);
router.patch("/users/:id", requireAuth, async (req, res) => {
  const { societyId, userId } = req.jwtUser!;
  const { ruolo, leva, stato } = req.body as Record<string, any>;

  // Gating LIVE: il chiamante deve essere admin/mister_admin nella sua società corrente.
  try {
    const [meRows] = (await pool.execute(
      "SELECT ruolo FROM users WHERE id = ? AND society_id = ? LIMIT 1",
      [userId, societyId]
    )) as [any[], any];
    const callerRuolo = meRows[0]?.ruolo as string | undefined;
    if (callerRuolo !== "admin" && callerRuolo !== "mister_admin") {
      return res.status(403).json({ error: "forbidden", detail: "Solo admin possono aggiornare il ruolo di altri utenti." });
    }
  } catch (e: any) {
    logger.error({ err: e }, "PATCH user — gating query error");
    return res.status(500).json({ error: "server_error" });
  }

  // Validazione whitelist ruolo (solo se presente).
  if (ruolo !== undefined && (typeof ruolo !== "string" || !PATCH_RUOLO_WHITELIST.has(ruolo))) {
    return res.status(400).json({ error: "invalid_ruolo", allowed: [...PATCH_RUOLO_WHITELIST] });
  }

  // Costruisci UPDATE con SOLO i campi presenti. email mai toccata (UNIQUE constraint).
  const updates: string[] = [];
  const params: any[] = [];
  if (ruolo !== undefined) { updates.push("ruolo = ?"); params.push(ruolo); }
  if (leva !== undefined)  { updates.push("leva = ?");  params.push(leva ?? null); }
  if (stato !== undefined) { updates.push("stato = ?"); params.push(String(stato)); }
  if (!updates.length) return res.status(400).json({ error: "nothing_to_update" });

  try {
    params.push(req.params.id, societyId);
    const [result] = (await pool.execute(
      `UPDATE users SET ${updates.join(", ")} WHERE id = ? AND society_id = ?`,
      params
    )) as [any, any];
    if (!result.affectedRows) return res.status(404).json({ error: "not_found" });
    return res.json({ ok: true, updated: result.affectedRows });
  } catch (e: any) {
    logger.error({ err: e }, "PATCH user error");
    return res.status(500).json({ error: "server_error" });
  }
});

// DELETE /api/v2/users/:id
router.delete("/users/:id", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId, userId } = req.jwtUser!;
  if (String(userId) === req.params.id) return res.status(400).json({ error: "cannot_delete_self" });

  try {
    const [result] = (await pool.execute(
      "DELETE FROM users WHERE id = ? AND society_id = ?",
      [req.params.id, societyId]
    )) as [any, any];
    if (!result.affectedRows) return res.status(404).json({ error: "not_found" });
    return res.json({ ok: true });
  } catch (e: any) {
    logger.error({ err: e }, "DELETE user error");
    return res.status(500).json({ error: "server_error" });
  }
});

// GET /api/v2/users/pending — utenti in attesa di approvazione
router.get("/users/pending", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId } = req.jwtUser!;
  try {
    const [rows] = (await pool.execute(
      "SELECT id, nome, cognome, email, created_at FROM users WHERE society_id = ? AND stato = 'pendente' ORDER BY created_at DESC",
      [societyId]
    )) as [any[], any];
    return res.json(rows);
  } catch (e: any) {
    return res.status(500).json({ error: "server_error" });
  }
});

// POST /api/v2/users/:id/approve
router.post("/users/:id/approve", requireAuth, requireRole("admin"), async (req, res) => {
  const { societyId } = req.jwtUser!;
  const { ruolo, leva, figli } = req.body as Record<string, any>;

  try {
    const [result] = (await pool.execute(
      `UPDATE users SET stato = 'attivo', ruolo = COALESCE(?, ruolo),
        leva = COALESCE(?, leva), figli = COALESCE(?, figli)
       WHERE id = ? AND society_id = ? AND stato = 'pendente'`,
      [ruolo ?? null, leva ?? null, figli ? JSON.stringify(figli) : null, req.params.id, societyId]
    )) as [any, any];
    if (!result.affectedRows) return res.status(404).json({ error: "not_found" });
    return res.json({ ok: true });
  } catch (e: any) {
    return res.status(500).json({ error: "server_error" });
  }
});

export default router;
